  Lemma afuzz_call : forall (regs : bvmap 5 word) (mem : mem) (msF : machine_state) (mo : Model)
      (s : as_St H) (LB : list block) (D N lo B shi : Z) (ds : list byte) (errv can : word) (ra : Z) (K : TSet),
    as_VIS H s msF = mkst regs (Z_to_bv 64 P_AFUZZ_ENTRY) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    getr regs 1 = Z_to_bv 64 ra -> 0 <= ra < 2 ^ 64 -> ra mod 2 = 0 ->
    getr regs 4 = Z_to_bv 64 ATP ->
    getr regs 10 = Z_to_bv 64 D -> getr regs 11 = Z_to_bv 64 N ->
    bytes_at bsegs mem D ds -> Z.of_nat (length ds) = N -> N < 2 ^ 26 -> D mod 16 = 0 ->
    (1 <= N -> exists pD, In (pD, D, N) LB) -> (N = 0 -> D = AFUZZ_EMPTY) ->
    as_RHEAP H s LB mem ->
    lb_bytes LB + AFUZZ_LIVE <= as_LIVE_MAX H -> Z.of_nat (length LB) + AFUZZ_CNT <= as_LIVE_CNT_MAX H ->
    as_rauxv_ok H mem B -> bv_unsigned (getr regs 2) <= B -> B < 2 ^ 64 ->
    bv_unsigned (getr regs 2) mod 16 = 0 ->
    stk bsegs mem lo (bv_unsigned (getr regs 2)) -> aceil <= lo -> lo <= bv_unsigned (getr regs 2) - AFUZZ_STACK ->
    bv_unsigned (getr regs 2) <= 0x7fffffffffff ->
    rw_cells bsegs mem (errno_addr (getr regs 4)) [C4 errv] -> mem_inv bsegs mem ->
    AXImg mem -> bytes_at bsegs mem ACANARY (word_to_le_bytes 8 can) -> HS mem -> ACONST mem ->
    (1 <= N -> addressable mem D N) ->
    as_RFS H [] mem -> stack0 mem lo shi -> bv_unsigned (getr regs 2) + 64 <= shi ->
    (bv_unsigned (getr regs 8) <= aceil \/ bv_unsigned (getr regs 8) mod 8 <> 0) ->       (* [comment removed for export] *)
    pf_ok (as_TR H) APF_FUZZ ra [] -> afuzz_tr_ok H ->
    afuzz_cost H N <= as_AL H s ->
    (forall (regs' : bvmap 5 word) (mem' : word -> option byte) (msF' : machine_state) (mo' : Model) (s' : as_St H)
            (LB' : list block) (XS : list (Z * Z)) (errv' : word),
        as_VIS H s' msF' = mkst regs' (Z_to_bv 64 ra) mem' rom -> as_AKREL H s' (mkCfg msF' mo') -> as_MPRES H mo mo' ->
        (forall r, In r aheap_kept -> getr regs' r = getr regs r) ->
        getr regs' 10 = Z_to_bv 64 0 ->
        mem_inv bsegs mem' -> stk bsegs mem' lo (bv_unsigned (getr regs 2)) ->
        rw_cells bsegs mem' (errno_addr (getr regs 4)) [C4 errv'] -> as_rauxv_ok H mem' B ->
        as_RHEAP H s' LB' mem' -> Permutation LB' LB ->
        Forall (fs_scratch H []) XS -> xpres H LB (bv_unsigned (getr regs 2)) (AXH_X ++ XS) mem mem' ->
        HS mem' ->
        as_RFS H [] mem' -> ACONST mem' -> stack0 mem' lo shi ->
        as_AL H s' >= as_AL H s - afuzz_cost H N ->
        realizes bsegs (mkCfg msF' mo') K) ->
    realizes bsegs (mkCfg msF mo) K.
